function [elementarea,elementfirstmomentx,elementsecondmomentx,elementfirstmomenty,elementsecondmomenty] =ElementalAreaMoments(nnps,ssfac,nqpts,swts,rjs,xsurf,ysurf)% % called by ComputeAreaMoments, which in turn is called by MechMet and MechModuli%% computes elemental area moment values%  needed for computing tractions from applied momentselementarea = 0;elementfirstmomentx = 0;elementsecondmomentx = 0;elementfirstmomenty = 0;elementsecondmomenty = 0;  for j=1:1:nqpts  	    xkfac=swts(j)*rjs(j);       qp_xy = [0 0];                                     for knp=1:1:nnps              qp_xy(1)=qp_xy(1) + ssfac(knp,j)*xsurf(knp);            qp_xy(2)=qp_xy(2) + ssfac(knp,j)*ysurf(knp);        end      elementarea = elementarea + xkfac;    elementfirstmomentx = elementfirstmomentx + qp_xy(1)*xkfac;    elementsecondmomentx = elementsecondmomentx+ qp_xy(1)^2*xkfac;        elementfirstmomenty = elementfirstmomenty + qp_xy(2)*xkfac;    elementsecondmomenty = elementsecondmomenty+ qp_xy(2)^2*xkfac;   end